     1→/**
     2→ * FreeLang Nexus - 코드 생성기
     3→ * AST → C 코드 (V 모드) + Python 코드 (Python 모드)
     4→ */
     5→
     6→import * as AST from '../parser/ast';
     7→
     8→export interface CodegenResult {
     9→  c: string;       // V 모드 함수들 → C 코드
    10→  python: string;  // Python 모드 함수들 → Python 코드
    11→  mixed: string;   // 두 코드 주석으로 구분 (디버그용)
    12→}
    13→
    14→export class NexusCodegen {
    15→  private cLines: string[] = [];
    16→  private pyLines: string[] = [];
    17→  private indentLevel: number = 0;
    18→
    19→  /**
    20→   * 프로그램 전체 코드 생성
    21→   */
    22→  generate(program: AST.Program): CodegenResult {
    23→    // @mode 마커는 무시하고 함수/문장만 처리
    24→    for (const item of program.body) {
    25→      const fnItem = item as any;
    26→      if (fnItem.type === 'VFunction') {
    27→        this.genVFunction(fnItem as AST.VFunction);
    28→      } else if (fnItem.type === 'PyFunction') {
    29→        this.genPyFunction(fnItem as AST.PyFunction);
    30→      } else if (fnItem.type === 'Return' || fnItem.type === 'Assign' || fnItem.type === 'ExprStatement') {
    31→        // 탑레벨 문장은 V 모드(C)로 처리
    32→        this.genVStatement(fnItem as AST.Statement);
    33→      }
    34→    }
    35→
    36→    const c = this.cLines.join('\n');
    37→    const python = this.pyLines.join('\n');
    38→
    39→    // mixed: 두 언어 코드를 주석으로 구분해서 출력 (확인용)
    40→    const mixed =
    41→      c && python
    42→        ? `/* ===== V (C) ===== */\n${c}\n\n/* ===== Python ===== */\n# (Not valid C, just for reference)\n${python}`
    43→        : c || python;
    44→
    45→    return { c, python, mixed };
    46→  }
    47→
    48→  /**
    49→   * V 함수 → C 함수
    50→   * fn add(x: i64, y: i64) -> i64 { return x + y }
    51→   * →
    52→   * long long add(long long x, long long y) { return x + y; }
    53→   */
    54→  private genVFunction(fn: AST.VFunction): void {
    55→    // 반환타입
    56→    const returnType = this.mapVType(fn.returnType || 'void');
    57→
    58→    // 파라미터 리스트
    59→    const paramList = fn.params.map((p) => `${this.mapVType(p.typeAnnotation || 'void')} ${p.name}`).join(', ');
    60→
    61→    // 함수 시그니처
    62→    this.writeC(`${returnType} ${fn.name}(${paramList}) {`);
    63→
    64→    // 함수 본문
    65→    this.indentLevel++;
    66→    for (const stmt of fn.body) {
    67→      this.genVStatement(stmt);
    68→    }
    69→    this.indentLevel--;
    70→
    71→    this.writeC('}');
    72→    this.writeC(''); // 빈 줄
    73→  }
    74→
    75→  /**
    76→   * Python 함수 → Python 함수
    77→   * def slow(items): return items
    78→   * →
    79→   * def slow(items):
    80→   *     return items
    81→   */
    82→  private genPyFunction(fn: AST.PyFunction): void {
    83→    // 파라미터 리스트
    84→    const paramList = fn.params.map((p) => p.name).join(', ');
    85→
    86→    // 함수 정의
    87→    this.writePy(`def ${fn.name}(${paramList}):`);
    88→
    89→    // 함수 본문 (들여쓰기 필요)
    90→    this.indentLevel++;
    91→    for (const stmt of fn.body) {
    92→      this.genPyStatement(stmt);
    93→    }
    94→    this.indentLevel--;
    95→
    96→    this.writePy(''); // 빈 줄
    97→  }
    98→
    99→  /**
   100→   * V 문장 생성 (C 코드용)
   101→   */
   102→  private genVStatement(stmt: AST.Statement): void {
   103→    const s = stmt as any;
   104→
   105→    if (s.type === 'Return') {
   106→      const returnStmt = s as AST.ReturnStatement;
   107→      if (returnStmt.value) {
   108→        const expr = this.genVExpression(returnStmt.value);
   109→        this.writeC(`${this.indent()}return ${expr};`);
   110→      } else {
   111→        this.writeC(`${this.indent()}return;`);
   112→      }
   113→    } else if (s.type === 'Assign') {
   114→      const assignStmt = s as AST.AssignStatement;
   115→      const expr = this.genVExpression(assignStmt.value);
   116→      // C에서는 타입을 추론할 수 없으므로 기본값으로 long long 사용
   117→      this.writeC(`${this.indent()}long long ${assignStmt.name} = ${expr};`);
   118→    } else if (s.type === 'ExprStatement') {
   119→      const exprStmt = s as AST.ExprStatement;
   120→      const expr = this.genVExpression(exprStmt.expression);
   121→      this.writeC(`${this.indent()}${expr};`);
   122→    }
   123→  }
   124→
   125→  /**
   126→   * Python 문장 생성 (Python 코드용)
   127→   */
   128→  private genPyStatement(stmt: AST.Statement): void {
   129→    const s = stmt as any;
   130→    const indentStr = this.indent();
   131→
   132→    if (s.type === 'Return') {
   133→      const returnStmt = s as AST.ReturnStatement;
   134→      if (returnStmt.value) {
   135→        const expr = this.genPyExpression(returnStmt.value);
   136→        this.writePy(`${indentStr}return ${expr}`);
   137→      } else {
   138→        this.writePy(`${indentStr}return`);
   139→      }
   140→    } else if (s.type === 'Assign') {
   141→      const assignStmt = s as AST.AssignStatement;
   142→      const expr = this.genPyExpression(assignStmt.value);
   143→      this.writePy(`${indentStr}${assignStmt.name} = ${expr}`);
   144→    } else if (s.type === 'ExprStatement') {
   145→      const exprStmt = s as AST.ExprStatement;
   146→      const expr = this.genPyExpression(exprStmt.expression);
   147→      this.writePy(`${indentStr}${expr}`);
   148→    }
   149→  }
   150→
   151→  /**
   152→   * V 표현식 생성 (C 코드용)
   153→   */
   154→  private genVExpression(expr: AST.Expression): string {
   155→    const e = expr as any;
   156→
   157→    if (e.type === 'Number') {
   158→      return (e as AST.NumberLiteral).value.toString();
   159→    }
   160→
   161→    if (e.type === 'String') {
   162→      return `"${(e as AST.StringLiteral).value}"`;
   163→    }
   164→
   165→    if (e.type === 'Identifier') {
   166→      return (e as AST.Identifier).name;
   167→    }
   168→
   169→    if (e.type === 'BinaryExpr') {
   170→      const binExpr = e as AST.BinaryExpr;
   171→      const left = this.genVExpression(binExpr.left);
   172→      const right = this.genVExpression(binExpr.right);
   173→      return `${left} ${binExpr.operator} ${right}`;
   174→    }
   175→
   176→    if (e.type === 'Call') {
   177→      const callExpr = e as AST.CallExpr;
   178→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genVExpression(callExpr.callee);
   179→      const args = callExpr.args.map((arg) => this.genVExpression(arg)).join(', ');
   180→      return `${callee}(${args})`;
   181→    }
   182→
   183→    return '';
   184→  }
   185→
   186→  /**
   187→   * Python 표현식 생성 (Python 코드용)
   188→   */
   189→  private genPyExpression(expr: AST.Expression): string {
   190→    const e = expr as any;
   191→
   192→    if (e.type === 'Number') {
   193→      return (e as AST.NumberLiteral).value.toString();
   194→    }
   195→
   196→    if (e.type === 'String') {
   197→      return `"${(e as AST.StringLiteral).value}"`;
   198→    }
   199→
   200→    if (e.type === 'Identifier') {
   201→      return (e as AST.Identifier).name;
   202→    }
   203→
   204→    if (e.type === 'BinaryExpr') {
   205→      const binExpr = e as AST.BinaryExpr;
   206→      const left = this.genPyExpression(binExpr.left);
   207→      const right = this.genPyExpression(binExpr.right);
   208→      return `${left} ${binExpr.operator} ${right}`;
   209→    }
   210→
   211→    if (e.type === 'Call') {
   212→      const callExpr = e as AST.CallExpr;
   213→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genPyExpression(callExpr.callee);
   214→      const args = callExpr.args.map((arg) => this.genPyExpression(arg)).join(', ');
   215→      return `${callee}(${args})`;
   216→    }
   217→
   218→    return '';
   219→  }
   220→
   221→  /**
   222→   * V 타입 → C 타입 매핑
   223→   */
   224→  private mapVType(type: string): string {
   225→    const mapping: Record<string, string> = {
   226→      i64: 'long long',
   227→      i32: 'int',
   228→      f64: 'double',
   229→      f32: 'float',
   230→      bool: 'bool',
   231→      string: 'char*',
   232→      void: 'void',
   233→    };
   234→
   235→    return mapping[type] || type;
   236→  }
   237→
   238→  /**
   239→   * Python 타입 → Python 타입 (기본값)
   240→   */
   241→  private mapPyType(type: string): string {
   242→    const mapping: Record<string, string> = {
   243→      i64: 'int',
   244→      i32: 'int',
   245→      f64: 'float',
   246→      f32: 'float',
   247→      bool: 'bool',
   248→      string: 'str',
   249→      void: 'None',
   250→      int: 'int',
   251→      float: 'float',
   252→    };
   253→
   254→    return mapping[type] || type;
   255→  }
   256→
   257→  /**
   258→   * C 코드에 줄 추가
   259→   */
   260→  private writeC(line: string): void {
   261→    this.cLines.push(line);
   262→  }
   263→
   264→  /**
   265→   * Python 코드에 줄 추가
   266→   */
   267→  private writePy(line: string): void {
   268→    this.pyLines.push(line);
   269→  }
   270→
   271→  /**
   272→   * 현재 들여쓰기 문자열
   273→   */
   274→  private indent(): string {
   275→    return '    '.repeat(this.indentLevel);
   276→  }
   277→}
   278→

