     1→/**
     2→ * FreeLang Nexus CodeGen - 단위 테스트
     3→ */
     4→
     5→import NexusLexer from '../src/nexus/lexer/nexus-lexer';
     6→import { NexusParser } from '../src/nexus/parser/nexus-parser';
     7→import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';
     8→
     9→describe('NexusCodegen - Phase 3 핵심 테스트', () => {
    10→  // ==================== Test 1: V 함수 → C 시그니처 ====================
    11→  test('V 함수 → C 시그니처: long long add(', () => {
    12→    const source = `@mode(v)
    13→fn add(x: i64, y: i64) -> i64 {
    14→  return x + y
    15→}`;
    16→    const lexer = new NexusLexer(source);
    17→    const tokens = lexer.tokenize();
    18→    const parser = new NexusParser(tokens);
    19→    const ast = parser.parse();
    20→    const codegen = new NexusCodegen();
    21→    const result = codegen.generate(ast);
    22→
    23→    expect(result.c).toContain('long long add(');
    24→    expect(result.c).toContain('long long x');
    25→    expect(result.c).toContain('long long y');
    26→  });
    27→
    28→  // ==================== Test 2: V 함수 → C 반환문 ====================
    29→  test('V 함수 → C 반환: return x + y;', () => {
    30→    const source = `@mode(v)
    31→fn add(x: i64, y: i64) -> i64 {
    32→  return x + y
    33→}`;
    34→    const lexer = new NexusLexer(source);
    35→    const tokens = lexer.tokenize();
    36→    const parser = new NexusParser(tokens);
    37→    const ast = parser.parse();
    38→    const codegen = new NexusCodegen();
    39→    const result = codegen.generate(ast);
    40→
    41→    expect(result.c).toContain('return x + y;');
    42→  });
    43→
    44→  // ==================== Test 3: Python 함수 → Python 코드 ====================
    45→  test('Python 함수 → Python: def slow(items):', () => {
    46→    const source = `@mode(python)
    47→def slow(items):
    48→  return items`;
    49→    const lexer = new NexusLexer(source);
    50→    const tokens = lexer.tokenize();
    51→    const parser = new NexusParser(tokens);
    52→    const ast = parser.parse();
    53→    const codegen = new NexusCodegen();
    54→    const result = codegen.generate(ast);
    55→
    56→    expect(result.python).toContain('def slow(items):');
    57→  });
    58→
    59→  // ==================== Test 4: Python 들여쓰기 ====================
    60→  test('Python 들여쓰기: return items', () => {
    61→    const source = `@mode(python)
    62→def process():
    63→  x = 1
    64→  return x`;
    65→    const lexer = new NexusLexer(source);
    66→    const tokens = lexer.tokenize();
    67→    const parser = new NexusParser(tokens);
    68→    const ast = parser.parse();
    69→    const codegen = new NexusCodegen();
    70→    const result = codegen.generate(ast);
    71→
    72→    // 들여쓰기 (4칸)가 포함되어야 함
    73→    expect(result.python).toContain('    return');
    74→    expect(result.python).toContain('    x = 1');
    75→  });
    76→
    77→  // ==================== Test 5: 혼합 모드 → 분리된 출력 ====================
    78→  test('혼합 모드: c와 python 필드 분리', () => {
    79→    const source = `@mode(v)
    80→fn fast(x: i64) -> i64 {
    81→  return x * x
    82→}
    83→
    84→@mode(python)
    85→def slow(items):
    86→  return items`;
    87→    const lexer = new NexusLexer(source);
    88→    const tokens = lexer.tokenize();
    89→    const parser = new NexusParser(tokens);
    90→    const ast = parser.parse();
    91→    const codegen = new NexusCodegen();
    92→    const result = codegen.generate(ast);
    93→
    94→    expect(result.c).toContain('long long fast');
    95→    expect(result.python).toContain('def slow');
    96→    expect(result.mixed).toContain('V (C)');
    97→    expect(result.mixed).toContain('Python');
    98→  });
    99→
   100→  // ==================== Test 6: 타입 변환 ====================
   101→  test('타입 변환: i64 → long long', () => {
   102→    const source = `@mode(v)
